mapper.insert:
INSERT INTO TB_USER_GROUP (user_id, vessel_id, group_id)
VALUES (#{userId}, #{vesselId}, #{groupId})
ON DUPLICATE KEY UPDATE group_id = #{groupId}

mapper.select:
SELECT v.vessel_id AS id, v.vessel_name AS name FROM tb_vessel v
JOIN tb_user_access ua ON v.vessel_id = ua.vessel_id WHERE ua.user_id = #{userId}
ORDER BY v.vessel_name ASC

mapper.update:
UPDATE tb_user
SET user_name = #{userName}

    , password = #{password}

WHERE user_id = #{userId}
